import { writeFile } from 'node:fs/promises';
import path from 'node:path';

import dynamicIconImports from 'lucide-react/dynamicIconImports.mjs';

const iconNames = Object.keys(dynamicIconImports).sort();
const outputPath = path.resolve(
  'src/shared/contracts/lucide-icon-catalog.generated.ts',
);
const source = `/**
 * Generated by \`pnpm run generate:icon-catalog\` from the installed
 * lucide-react package. Do not edit this file by hand.
 */
export const PROJECT_ICON_IDS = ${JSON.stringify(iconNames, null, 2)} as const;

export type ProjectIconId = (typeof PROJECT_ICON_IDS)[number];
`;

await writeFile(outputPath, source, 'utf8');
